// Sem0 — Build Prompt (product_kind / product_family / attr_profile).
// No category_id / direction / need. Soft-continue into Sem1.

const DRUG_FAMILIES = [
  'кожные заболевания',
  'простуда и ОРВИ',
  'ЖКТ',
  'Кровь / Кровеносная система',
  'Нервная система',
  'Боль и Температура',
  'Сердце и сосуды',
  'Опорно-двигательный аппарат',
  'Кашель',
  'Урология',
  'Слух и зрение',
  'Гормоны',
  'Стоматология',
  'Бактериофаги',
  'Противоклещевые',
  'Инъекции',
  'Инфузии',
  'Гомеопатия',
  'Травы',
];

const DEVICE_FAMILIES = [
  'Измерительные приборы',
  'Гигиена и косметика',
  'Товары для мам и детей',
  'Приборы для терапии',
  'Приборы и средства для инъекций',
  'Перевязочные материалы',
  'Пластыри',
  'Другое медизделие',
];

return items.map((item, index) => {
  const j = item.json || {};
  const shortlist = Array.isArray(j.shortlist_json) ? j.shortlist_json : [];

  const shortlistHint = shortlist.length
    ? shortlist
        .slice(0, 5)
        .map((c, idx) => {
          const name = c.category_name || c.name || '';
          const code = c.category_code || c.code || '';
          return `${idx + 1}. code=${code}, name=${name}`;
        })
        .join('\n')
    : 'NONE';

  const attrHints = {
    norm_mnn_product: j.norm_mnn_product ?? null,
    norm_brand_guess: j.norm_brand_guess ?? null,
    norm_form_guess: j.norm_form_guess ?? null,
    norm_dosage_guess: j.norm_dosage_guess ?? null,
    norm_pack_size_guess: j.norm_pack_size_guess ?? null,
    norm_product_type_guess: j.norm_product_type_guess ?? j.product_type_guess ?? null,
  };

  const promptSystem =
    'You analyze a pharmacy product and determine its top-level kind, therapeutic or usage family, and which semantic attributes are applicable.\n\n' +
    'Return ONLY valid JSON with keys:\n' +
    'product_kind, product_family, attr_profile, confidence, explanation.\n\n' +
    'Do NOT return category_id, direction, need, block_family, or any leaf category.\n\n' +
    'product_kind must be one of: drug, vitamin_or_baa, medical_device, cosmetic_hygiene, other.\n' +
    'attr_profile must contain all keys mnn, brand, rx_otc, nosology, administration_route, dosage_form, dosage, age_segment, package_hint, combination_hint with values "applicable" or "not_applicable".\n\n' +
    'For vitamin_or_baa: set mnn, rx_otc, nosology to not_applicable.\n' +
    'For medical_device / cosmetic_hygiene / other: set mnn, rx_otc, nosology, administration_route, dosage_form, dosage, combination_hint to not_applicable unless clearly needed (e.g. plaster may allow route/form/dosage as device packaging).\n' +
    'For drug: pharma attrs are usually applicable.\n\n' +
    'confidence must be a number from 0.0 to 1.0.\n' +
    'explanation must be a short Russian string (1–3 sentences).';

  const promptUser = `
Товар (normalized_text):
${j.normalized_text || j.combined_text || ''}

Подсказки после Norm (могут быть null):
${JSON.stringify(attrHints, null, 2)}

Мягкая подсказка Stage 1 shortlist (НЕ обязательный набор):
${shortlistHint}

normalize_meta:
${JSON.stringify(j.normalize_meta || {}, null, 2)}

Списки product_family:
- если product_kind=drug, выбери один из: ${DRUG_FAMILIES.join('; ')}
- если product_kind=medical_device, выбери один из: ${DEVICE_FAMILIES.join('; ')}
- если product_kind=vitamin_or_baa: свободный короткий текст или null
- иначе: null

Задача:
- Определи верхний тип товара (product_kind): drug, vitamin_or_baa, medical_device, cosmetic_hygiene или other.
- Определи product_family по правилам выше (или null).
- Заполни attr_profile: для каждого атрибута "applicable" или "not_applicable".
  Пример гигиены (ватные палочки): mnn/rx_otc/nosology/administration_route/dosage_form/dosage/combination_hint = not_applicable; brand/age_segment/package_hint = applicable.
- Не выдумывай фармакологические свойства для товаров, которые не являются лекарствами.
- Верни только JSON без markdown.
`.trim();

  return {
    json: {
      ...j,
      prompt_system: promptSystem,
      prompt_user: promptUser,
      llm_prompt_debug: {
        system: promptSystem,
        user: promptUser,
        stage: 'sem0',
      },
    },
    pairedItem: index,
  };
});

// Sem0 — LLM Prepare (product_kind_select).

function withoutStaleLlmOutput(j) {
  const src = j || {};
  const {
    output,
    text,
    response,
    content,
    result,
    llm_raw_output_text,
    ...rest
  } = src;
  return rest;
}

return items.map((item, index) => {
  const j = withoutStaleLlmOutput(item.json);
  const WORKFLOW_VERSION = 'stage2_hierarchy_v1';
  const PROMPT_VERSION = 'prompt_sem0_v1';
  const C = j.constants || {};

  return {
    json: {
      ...j,
      workflow_version: WORKFLOW_VERSION,
      prompt_version: PROMPT_VERSION,
      stage: 'product_kind_select',
      actor_type: (C.actor_type && C.actor_type.llm) || 'llm',
      actor_name:
        (C.model && C.model.cascade_actor_name) ||
        (C.model && C.model.primary_actor_name) ||
        'deepseek-chat',
      context: {
        run_id:
          j.run_id !== undefined && j.run_id !== null && j.run_id !== ''
            ? Number(j.run_id)
            : null,
        product_id:
          j.product_id !== undefined && j.product_id !== null && j.product_id !== ''
            ? Number(j.product_id)
            : null,
        product_raw_id:
          j.product_raw_id !== undefined && j.product_raw_id !== null && j.product_raw_id !== ''
            ? Number(j.product_raw_id)
            : null,
        normalized_text: j.normalized_text ?? null,
        normalize_meta: j.normalize_meta ?? null,
        norm_warnings: j.norm_warnings ?? [],
        shortlist_json: Array.isArray(j.shortlist_json) ? j.shortlist_json : [],
      },
      prompt_system: j.prompt_system || '',
      prompt_user: j.prompt_user || '',
    },
    pairedItem: index,
  };
});

// Sem0 — Post-process (product_kind / attr_profile).
// Soft-continue always into Sem1. On failure: product_kind=other, all attrs applicable.

function extractJsonString(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'object') return JSON.stringify(value);
  let text = String(value).trim();
  const codeFenceMatch = text.match(/^```(?:json)?\s*\n?([\s\S]+?)\n?```\s*$/i);
  if (codeFenceMatch) text = codeFenceMatch[1].trim();
  return text;
}

function safeParseJson(value) {
  const text = extractJsonString(value);
  if (!text) return { ok: false, error: 'empty_output', parsed: null, raw_text: null };
  try {
    return { ok: true, error: null, parsed: JSON.parse(text), raw_text: text };
  } catch (e) {
    return { ok: false, error: 'invalid_json', parsed: null, raw_text: text };
  }
}

function normalizeConfidence(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  if (n < 0 || n > 1) return null;
  return n;
}

function safeText(v) {
  if (v === undefined || v === null || v === '') return null;
  const s = String(v).trim();
  return s === '' ? null : s;
}

function pickLlmRaw(root) {
  if (root.output !== undefined) return root.output;
  if (root.text !== undefined) return root.text;
  if (root.response !== undefined) return root.response;
  if (root.content !== undefined) return root.content;
  if (root.result !== undefined) return root.result;
  return null;
}

const ATTR_KEYS = [
  'mnn',
  'brand',
  'rx_otc',
  'nosology',
  'administration_route',
  'dosage_form',
  'dosage',
  'age_segment',
  'package_hint',
  'combination_hint',
];

const KIND_ALLOWED = new Set([
  'drug',
  'vitamin_or_baa',
  'medical_device',
  'cosmetic_hygiene',
  'other',
]);

const STAGE = 'product_kind_select';

function allApplicableProfile() {
  const out = {};
  for (const k of ATTR_KEYS) out[k] = 'applicable';
  return out;
}

function normalizeAttrProfile(raw) {
  const src = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
  const out = {};
  for (const k of ATTR_KEYS) {
    const v = String(src[k] || '').trim().toLowerCase();
    out[k] = v === 'not_applicable' ? 'not_applicable' : 'applicable';
  }
  return out;
}

return items.map((item, index) => {
  const root = item.json || {};
  const C = root.constants || {};
  const ACTOR_LLM = (C.actor_type && C.actor_type.llm) || 'llm';
  const MODEL_NAME =
    (C.model && C.model.cascade_actor_name) ||
    (C.model && C.model.primary_actor_name) ||
    'deepseek-chat';

  const raw = pickLlmRaw(root);
  const parsed = safeParseJson(raw);

  let validationPassed = false;
  let rejectReason = null;
  let productKind = 'other';
  let productFamily = null;
  let attrProfile = allApplicableProfile();
  let confidence = null;
  let explanation = null;

  if (!parsed.ok) {
    rejectReason = parsed.error || 'empty_output';
  } else if (!parsed.parsed || typeof parsed.parsed !== 'object' || Array.isArray(parsed.parsed)) {
    rejectReason = 'invalid_shape';
  } else {
    const obj = parsed.parsed;
    if (obj.category_id !== undefined && obj.category_id !== null && String(obj.category_id).trim() !== '') {
      rejectReason = 'category_id_forbidden';
    } else if (obj.direction !== undefined && obj.direction !== null && String(obj.direction).trim() !== '') {
      rejectReason = 'direction_forbidden';
    } else if (obj.need !== undefined && obj.need !== null && String(obj.need).trim() !== '') {
      rejectReason = 'need_forbidden';
    } else {
      const kind = safeText(obj.product_kind);
      const conf = normalizeConfidence(obj.confidence);
      const expl = safeText(obj.explanation);
      if (!kind || !KIND_ALLOWED.has(kind)) {
        rejectReason = 'invalid_product_kind';
      } else if (conf === null) {
        rejectReason = 'invalid_confidence';
      } else if (expl === null) {
        rejectReason = 'missing_explanation';
        productKind = kind;
        productFamily = safeText(obj.product_family);
        attrProfile = normalizeAttrProfile(obj.attr_profile);
        confidence = conf;
      } else {
        productKind = kind;
        productFamily = safeText(obj.product_family);
        attrProfile = normalizeAttrProfile(obj.attr_profile);
        confidence = conf;
        explanation = expl;
        validationPassed = true;
        rejectReason = null;
      }
    }
  }

  // Soft-fail: other + all applicable (do not regress drugs when Sem0 breaks).
  if (!validationPassed && rejectReason && rejectReason !== 'missing_explanation') {
    productKind = 'other';
    productFamily = null;
    attrProfile = allApplicableProfile();
  }

  const prevTrace =
    root.cascade_trace && typeof root.cascade_trace === 'object' && !Array.isArray(root.cascade_trace)
      ? root.cascade_trace
      : {};
  const path = Array.isArray(prevTrace.path) ? [...prevTrace.path] : [];
  if (!path.includes(STAGE)) path.push(STAGE);
  const stages = Array.isArray(prevTrace.stages) ? [...prevTrace.stages] : [];
  stages.push({
    stage: STAGE,
    actor_type: ACTOR_LLM,
    actor_name: MODEL_NAME,
    validation_passed: validationPassed,
    reject_reason: rejectReason,
    notes: 'sem0_v1',
  });

  // Strip Sem0 LLM output fields so Sem1 starts clean.
  const {
    output,
    text,
    response,
    content,
    result,
    llm_raw_output_text,
    prompt_system,
    prompt_user,
    llm_prompt_debug,
    ...rest
  } = root;

  return {
    json: {
      ...rest,
      workflow_version: root.workflow_version || 'stage2_hierarchy_v1',
      prompt_version: 'prompt_sem0_v1',
      stage: STAGE,
      actor_type: ACTOR_LLM,
      actor_name: MODEL_NAME,
      product_kind: productKind,
      product_family: productFamily,
      attr_profile: attrProfile,
      sem0_confidence: confidence,
      sem0_explanation: explanation,
      sem0_validation_passed: validationPassed,
      sem0_reject_reason: rejectReason,
      sem0_raw_json: parsed.raw_text
        ? { raw_text: parsed.raw_text, parsed: parsed.parsed }
        : raw !== null && raw !== undefined
          ? { raw: raw }
          : null,
      selected_category_id: null,
      cascade_trace: {
        ...prevTrace,
        path,
        stages,
      },
    },
    pairedItem: index,
  };
});

// Sem — Build Prompt (hierarchy B3 Sem / semantic_primary v2).
// Uses Sem0 product_kind / product_family / attr_profile hints.
// No category_id / direction / need selection.

return items.map((item, index) => {
  const j = item.json || {};
  const shortlist = Array.isArray(j.shortlist_json) ? j.shortlist_json : [];

  const shortlistHint = shortlist.length
    ? shortlist
        .slice(0, 5)
        .map((c, idx) => {
          const name = c.category_name || c.name || '';
          const code = c.category_code || c.code || '';
          return `${idx + 1}. code=${code}, name=${name}`;
        })
        .join('\n')
    : 'NONE';

  const attrHints = {
    norm_mnn_product: j.norm_mnn_product ?? null,
    norm_brand_guess: j.norm_brand_guess ?? null,
    norm_form_guess: j.norm_form_guess ?? null,
    norm_dosage_guess: j.norm_dosage_guess ?? null,
    norm_pack_size_guess: j.norm_pack_size_guess ?? null,
    norm_product_type_guess: j.norm_product_type_guess ?? j.product_type_guess ?? null,
    product_kind: j.product_kind ?? null,
    product_family: j.product_family ?? null,
    attr_profile: j.attr_profile ?? null,
  };

  const promptSystem =
    'You extract semantic attributes for a pharmacy product. Return ONLY valid JSON with keys: mnn, brand, rx_otc, nosology, administration_route, dosage_form, dosage, age_segment, package_hint, combination_hint, confidence, explanation. Do NOT return category_id, direction, need, block_family, or any final leaf category. All attribute fields may be null. confidence must be a number from 0.0 to 1.0. explanation must be a short Russian string (1–3 sentences).\n\n' +
    'Учитывай attr_profile из подсказок:\n' +
    '- Если для поля в attr_profile указано "not_applicable", возвращай для него null и НЕ пытайся его угадывать.\n' +
    '- Если product_kind != "drug":\n' +
    '  - НЕ заполняй mnn, rx_otc, nosology, administration_route, dosage_form, dosage, combination_hint (верни null).\n' +
    '  - Для medical_device и cosmetic_hygiene можешь заполнять только brand, age_segment, package_hint при наличии сигнала.\n' +
    '- В explanation кратко упомяни, что товар не является лекарственным средством, если это так, и поэтому часть полей не применима.';

  const promptUser = `
Товар (normalized_text):
${j.normalized_text || j.combined_text || ''}

Подсказки после Norm / Sem0 (могут быть null):
${JSON.stringify(attrHints, null, 2)}

Мягкая подсказка Stage 1 shortlist (НЕ обязательный набор, НЕ выбирай category_id):
${shortlistHint}

normalize_meta:
${JSON.stringify(j.normalize_meta || {}, null, 2)}

Задача:
- Извлеки семантические атрибуты товара с учётом product_kind / attr_profile.
- НЕ выбирай category_id / направление / потребность / финальную категорию.
- Если признак неизвестен или not_applicable — верни null (не выдумывай).
- confidence: 0.0–1.0; explanation: 1–3 предложения на русском.
- Верни только JSON без markdown.
`.trim();

  return {
    json: {
      ...j,
      prompt_system: promptSystem,
      prompt_user: promptUser,
      llm_prompt_debug: {
        system: promptSystem,
        user: promptUser,
      },
    },
    pairedItem: index,
  };
});

// Sem — LLM Prepare (hierarchy B3 Sem).

function withoutStaleLlmOutput(j) {
  const src = j || {};
  const {
    output,
    text,
    response,
    content,
    result,
    llm_raw_output_text,
    ...rest
  } = src;
  return rest;
}

return items.map((item, index) => {
  const j = withoutStaleLlmOutput(item.json);
  const WORKFLOW_VERSION = 'stage2_hierarchy_v1';
  const PROMPT_VERSION = 'prompt_semantic_v2';
  const C = j.constants || {};

  return {
    json: {
      ...j,
      workflow_version: WORKFLOW_VERSION,
      prompt_version: PROMPT_VERSION,
      stage: (C.stage && C.stage.semantic_primary) || 'semantic_primary',
      actor_type: (C.actor_type && C.actor_type.llm) || 'llm',
      actor_name:
        (C.model && C.model.cascade_actor_name) ||
        (C.model && C.model.primary_actor_name) ||
        'deepseek-chat',
      context: {
        run_id:
          j.run_id !== undefined && j.run_id !== null && j.run_id !== ''
            ? Number(j.run_id)
            : null,
        product_id:
          j.product_id !== undefined && j.product_id !== null && j.product_id !== ''
            ? Number(j.product_id)
            : null,
        product_raw_id:
          j.product_raw_id !== undefined && j.product_raw_id !== null && j.product_raw_id !== ''
            ? Number(j.product_raw_id)
            : null,
        normalized_text: j.normalized_text ?? null,
        normalize_meta: j.normalize_meta ?? null,
        norm_warnings: j.norm_warnings ?? [],
        shortlist_json: Array.isArray(j.shortlist_json) ? j.shortlist_json : [],
      },
      prompt_system: j.prompt_system || '',
      prompt_user: j.prompt_user || '',
    },
    pairedItem: index,
  };
});

// Sem — Post-process (hierarchy B3 Sem).
// Soft-continue always → next_action=direction_select.
// Never classified. Never persist category_id from Sem.

function extractJsonString(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'object') return JSON.stringify(value);
  let text = String(value).trim();
  const codeFenceMatch = text.match(/^```(?:json)?\s*\n?([\s\S]+?)\n?```\s*$/i);
  if (codeFenceMatch) text = codeFenceMatch[1].trim();
  return text;
}

function safeParseJson(value) {
  const text = extractJsonString(value);
  if (!text) return { ok: false, error: 'empty_output', parsed: null, raw_text: null };
  try {
    return { ok: true, error: null, parsed: JSON.parse(text), raw_text: text };
  } catch (e) {
    return { ok: false, error: 'invalid_json', parsed: null, raw_text: text };
  }
}

function normalizeConfidence(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  if (n < 0 || n > 1) return null;
  return n;
}

function safeText(v) {
  if (v === undefined || v === null || v === '') return null;
  const s = String(v).trim();
  return s === '' ? null : s;
}

function pickLlmRaw(root) {
  if (root.output !== undefined) return root.output;
  if (root.text !== undefined) return root.text;
  if (root.response !== undefined) return root.response;
  if (root.content !== undefined) return root.content;
  if (root.result !== undefined) return root.result;
  return null;
}

const ATTR_KEYS = [
  'mnn',
  'brand',
  'rx_otc',
  'nosology',
  'administration_route',
  'dosage_form',
  'dosage',
  'age_segment',
  'package_hint',
  'combination_hint',
];

const RX_OTC_ALLOWED = new Set(['rx', 'otc', 'unknown', null]);

return items.map((item, index) => {
  const root = item.json || {};
  const ctx = root.context || {};
  const C = root.constants || {};

  const WORKFLOW_VERSION = root.workflow_version || 'stage2_hierarchy_v1';
  const PROMPT_VERSION = 'prompt_semantic_v2';
  const STAGE = (C.stage && C.stage.semantic_primary) || 'semantic_primary';
  const productKind = safeText(root.product_kind) || 'other';
  const productFamily = safeText(root.product_family);
  const attrProfile =
    root.attr_profile && typeof root.attr_profile === 'object' && !Array.isArray(root.attr_profile)
      ? root.attr_profile
      : {};
  const DECISION_PENDING =
    (C.decision_status && C.decision_status.pending_fallback) || 'pending_fallback';
  const NEXT_DIR =
    (C.next_action && C.next_action.direction_select) || 'direction_select';
  const ACTOR_LLM = (C.actor_type && C.actor_type.llm) || 'llm';
  const LOG = C.log_status || {
    success: 'success',
    rejected: 'rejected',
    needs_review: 'needs_review',
  };
  const MODEL_NAME =
    (C.model && C.model.cascade_actor_name) ||
    (C.model && C.model.primary_actor_name) ||
    'deepseek-chat';

  const raw = pickLlmRaw(root);
  const parsed = safeParseJson(raw);

  let validationPassed = false;
  let rejectReason = null;
  let semanticAttrs = null;
  let semanticConfidence = null;
  let semanticExplanation = null;
  let logStatus = LOG.rejected || 'rejected';

  if (!parsed.ok) {
    rejectReason = parsed.error || 'empty_output';
  } else if (!parsed.parsed || typeof parsed.parsed !== 'object' || Array.isArray(parsed.parsed)) {
    rejectReason = 'invalid_shape';
  } else {
    const obj = parsed.parsed;
    const forbiddenCat = obj.category_id;
    if (forbiddenCat !== undefined && forbiddenCat !== null && String(forbiddenCat).trim() !== '') {
      rejectReason = 'category_id_forbidden';
    } else if (
      obj.direction !== undefined &&
      obj.direction !== null &&
      String(obj.direction).trim() !== ''
    ) {
      rejectReason = 'direction_forbidden';
    } else if (obj.need !== undefined && obj.need !== null && String(obj.need).trim() !== '') {
      rejectReason = 'need_forbidden';
    } else {
      const conf = normalizeConfidence(obj.confidence);
      const explanation = safeText(obj.explanation);
      if (conf === null) {
        rejectReason = 'invalid_confidence';
      } else if (explanation === null) {
        // soft-continue per migration: missing explanation only
        rejectReason = 'missing_explanation';
        semanticConfidence = conf;
        semanticAttrs = {};
        for (const key of ATTR_KEYS) {
          if (key === 'rx_otc') {
            const rx = safeText(obj.rx_otc);
            semanticAttrs.rx_otc =
              rx === null ? null : RX_OTC_ALLOWED.has(rx.toLowerCase()) ? rx.toLowerCase() : rx;
          } else {
            semanticAttrs[key] = safeText(obj[key]);
          }
        }
        semanticExplanation = null;
        validationPassed = false;
        logStatus = LOG.needs_review || 'needs_review';
      } else {
        semanticConfidence = conf;
        semanticExplanation = explanation;
        semanticAttrs = {};
        for (const key of ATTR_KEYS) {
          if (key === 'rx_otc') {
            const rx = safeText(obj.rx_otc);
            if (rx === null) semanticAttrs.rx_otc = null;
            else if (RX_OTC_ALLOWED.has(rx.toLowerCase())) semanticAttrs.rx_otc = rx.toLowerCase();
            else {
              semanticAttrs.rx_otc = rx;
              // non-fatal: keep attr, mark soft warning via reject_reason only if otherwise OK
            }
          } else {
            semanticAttrs[key] = safeText(obj[key]);
          }
        }
        validationPassed = true;
        rejectReason = null;
        logStatus = LOG.success || 'success';
      }
    }
  }

  // Enforce Sem0 attr_profile + non-drug pharma nulls.
  if (semanticAttrs && typeof semanticAttrs === 'object') {
    for (const key of ATTR_KEYS) {
      if (attrProfile[key] === 'not_applicable') {
        semanticAttrs[key] = null;
      }
    }
    if (productKind !== 'drug') {
      semanticAttrs.mnn = null;
      semanticAttrs.rx_otc = null;
      semanticAttrs.nosology = null;
      semanticAttrs.administration_route = null;
      semanticAttrs.dosage_form = null;
      semanticAttrs.dosage = null;
      semanticAttrs.combination_hint = null;
    }
    semanticAttrs.product_kind = productKind;
    semanticAttrs.product_family = productFamily;
    semanticAttrs.attr_profile = attrProfile;
  }

  // Always soft-continue to Dir seam; never classified at Sem.
  const decisionStatus = DECISION_PENDING;
  const nextAction = NEXT_DIR;

  const prevTrace =
    root.cascade_trace && typeof root.cascade_trace === 'object' && !Array.isArray(root.cascade_trace)
      ? root.cascade_trace
      : {};
  const path = Array.isArray(prevTrace.path) ? [...prevTrace.path] : [];
  if (!path.includes(STAGE)) path.push(STAGE);
  const stages = Array.isArray(prevTrace.stages) ? [...prevTrace.stages] : [];
  stages.push({
    stage: STAGE,
    actor_type: ACTOR_LLM,
    actor_name: MODEL_NAME,
    validation_passed: validationPassed,
    reject_reason: rejectReason,
    notes: 'semantic_primary_v2',
  });

  const routingHint = {
    sem_soft_continue: true,
    semantic_validation_passed: validationPassed,
    semantic_reject_reason: rejectReason,
    next_stage: NEXT_DIR,
  };

  return {
    json: {
      ...root,
      workflow_version: WORKFLOW_VERSION,
      prompt_version: PROMPT_VERSION,
      stage: STAGE,
      actor_type: ACTOR_LLM,
      actor_name: MODEL_NAME,
      semantic_attrs: semanticAttrs,
      semantic_confidence: semanticConfidence,
      semantic_explanation: semanticExplanation,
      semantic_raw_json: parsed.raw_text
        ? { raw_text: parsed.raw_text, parsed: parsed.parsed }
        : raw !== null && raw !== undefined
          ? { raw: raw }
          : null,
      semantic_validation_passed: validationPassed,
      semantic_reject_reason: rejectReason,
      decision_status: decisionStatus,
      next_action: nextAction,
      routing_hint: routingHint,
      log_status: logStatus,
      // Explicit: Sem never sets category
      selected_category_id: null,
      cascade_trace: {
        ...prevTrace,
        path,
        stages,
      },
    },
    pairedItem: index,
  };
});

// Sem — Prepare Log (hierarchy-specific, B3 Sem).
// stage=semantic_primary; selected_category_id=null;
// decision_status=pending_fallback; next_action=direction_select.
// Does NOT prepare snapshot upsert.

function sqlText(value) {
  if (value === undefined || value === null) return null;
  const s = String(value).trim();
  return s === '' ? null : s;
}

function sqlNumber(value) {
  if (value === undefined || value === null || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function sqlBoolean(value) {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value !== 0;
  if (typeof value === 'string') {
    const v = value.trim().toLowerCase();
    if (['true', '1', 'yes', 'y'].includes(v)) return true;
    if (['false', '0', 'no', 'n'].includes(v)) return false;
  }
  return null;
}

function sqlJson(value) {
  if (value === undefined || value === null || value === '') return null;
  return value;
}

return items.map((item, index) => {
  const j = item.json || {};
  const C = j.constants || {};

  const stage =
    sqlText(j.stage) ||
    (C.stage && C.stage.semantic_primary) ||
    'semantic_primary';
  const decisionStatus =
    sqlText(j.decision_status) ||
    (C.decision_status && C.decision_status.pending_fallback) ||
    'pending_fallback';
  const nextAction =
    sqlText(j.next_action) ||
    (C.next_action && C.next_action.direction_select) ||
    'direction_select';
  const actorType = sqlText(j.actor_type) || 'llm';
  const actorName = sqlText(j.actor_name) || 'deepseek-chat';
  const workflowVersion = sqlText(j.workflow_version) || 'stage2_hierarchy_v1';
  const promptVersion = sqlText(j.prompt_version) || 'prompt_semantic_v2';

  const inputPayload = {
    product_id: sqlNumber(j.product_id),
    product_raw_id: sqlNumber(j.product_raw_id),
    run_id: sqlNumber(j.run_id),
    stage,
    workflow_version: workflowVersion,
    prompt_version: promptVersion,
    normalized_text: sqlText(j.normalized_text),
    combined_text: sqlText(j.combined_text),
    normalize_meta: sqlJson(j.normalize_meta),
    norm_warnings: sqlJson(j.norm_warnings),
    norm_mnn_product: sqlText(j.norm_mnn_product),
    product_type_guess: sqlText(j.product_type_guess),
    rule_top_category_id: sqlNumber(j.rule_top_category_id),
    rule_top_score: sqlNumber(j.rule_top_score),
    shortlist_json: sqlJson(j.shortlist_json),
  };

  const outputPayload = {
    semantic_attrs: sqlJson(j.semantic_attrs),
    semantic_confidence: sqlNumber(j.semantic_confidence),
    semantic_explanation: sqlText(j.semantic_explanation),
    semantic_raw_json: sqlJson(j.semantic_raw_json),
    semantic_validation_passed: sqlBoolean(j.semantic_validation_passed),
    semantic_reject_reason: sqlText(j.semantic_reject_reason),
    selected_category_id: null,
    decision_status: decisionStatus,
    next_action: nextAction,
    routing_hint: sqlJson(j.routing_hint),
    cascade_trace: sqlJson(j.cascade_trace),
  };

  const status =
    sqlText(j.log_status) ||
    (j.semantic_validation_passed === true
      ? 'success'
      : j.semantic_reject_reason
        ? 'rejected'
        : 'needs_review');

  const productClassificationLogInsert = {
    run_id: sqlNumber(j.run_id),
    product_id: sqlNumber(j.product_id),
    product_raw_id: sqlNumber(j.product_raw_id),
    stage,
    actor_type: actorType,
    actor_name: actorName,
    status,
    input_payload: sqlJson(inputPayload),
    output_payload: sqlJson(outputPayload),
    selected_category_id: null,
    confidence: sqlNumber(j.semantic_confidence),
    explanation: sqlText(j.semantic_explanation),
    validation_passed: sqlBoolean(j.semantic_validation_passed),
    error_message: sqlText(j.semantic_reject_reason),
    workflow_version: workflowVersion,
    prompt_version: promptVersion,
    decision_status: decisionStatus,
    next_action: nextAction,
    routing_hint: sqlJson(j.routing_hint),
  };

  return {
    json: {
      ...j,
      stage,
      decision_status: decisionStatus,
      next_action: nextAction,
      selected_category_id: null,
      product_classification_log_insert: productClassificationLogInsert,
    },
    pairedItem: { item: index },
  };
});
